{"question": "周末和工作日外卖平均各花多少", "code": "def analyze(transactions):
    wk = []
    wd = []
    for t in transactions:
        if t.get("category") != "餐饮外卖":
            continue
        a = -t["amount"]
        if a <= 0:
            continue
        if t["weekday"] >= 5:
            wk.append(a)
        else:
            wd.append(a)
    def s(x):
        return {"笔数": len(x), "总额": round(sum(x), 2), "平均每笔": round(sum(x)/len(x), 2) if x else 0}
    return {"工作日": s(wd), "周末": s(wk)}"}
